Retrieved from TidyTuesday:
https://github.com/rfordatascience/tidytuesday/blob/main/data/2025/2025-05-06/readme.md
The dataset includes information on grants for scientific research and education projects from the U.S. National Science Foundation (NSF) that have been terminated by the Trump administration in 2025. The data was collected by Grant Watch through crowdsourcing from researchers and program administrators, as the administration has not released information on these terminations.


Code
nsf |&gt; 
    group_by(termination_letter_date) |&gt; 
    summarize(num_perday = n()) |&gt; 
    ggplot(aes(x=termination_letter_date,
        y=num_perday)) +
        geom_line() +
        geom_point() +
        labs(
            title = "NSF Grant Terminations Per Day",
            x = "Termination date",
            y = "Number of terminated grants")












Code
nsf |&gt; 
    filter(!is.na(division)) |&gt; 
    group_by(division) |&gt;
    summarize(num = n()) |&gt; 
    filter(num &gt; 100) |&gt; 
    ggplot(aes(x=num,y = fct_reorder(division, num)))+
        geom_col(fill = "#c84545") +
        labs(
            title = "NSF Grant Terminations by Division",
            subtitle = "Divisions with over 100 terminations",
            x = "Number of Grants Terminated",
            y = NULL
        ) +
        theme_minimal()











Code
nsf |&gt; 
    filter(!is.na(directorate)) |&gt; 
    group_by(directorate) |&gt;
    summarize(num = n()) |&gt; 
    arrange(desc(num)) |&gt; 
    slice_head(n = 4) |&gt; 
    ggplot(aes(x=num,y = fct_reorder(directorate, num)))+
        geom_col(fill = "#c84545") +
        labs(
            title = "NSF Grant Terminations by Directorate",
            subtitle = "the NSF organization that administered the grant ",
            x = "Number of Grants Terminated",
            y = NULL
        ) +
        theme_minimal()











Code
nsf |&gt; 
    group_by(award_type) |&gt; 
    summarize(num_term = n()) |&gt; 
    mutate(perc = num_term/sum(num_term)) |&gt; 
    ggplot(aes(x="",y = num_term, fill = award_type)) +
        geom_col() +
        coord_polar(theta = "y") +
        labs(
            title = "NSF Terminations by Award Type",
            fill = "Award Type"
        ) +
    theme_void()











Code
org_dollar &lt;- nsf |&gt;
  filter(!is.na(org_name), !is.na(usaspending_obligated)) |&gt;
  group_by(org_name) |&gt;
  summarize(
    n_terminations = n(),
    total_dollars = sum(usaspending_obligated)
  )

ggplot(org_dollar, aes(x = n_terminations, y = total_dollars)) +
  geom_point(alpha = 0.6, color = "#2c7fb8") +
  scale_x_log10() +
  scale_y_log10(labels = scales::label_dollar(scale = 1e-6, suffix = "M")) +
  labs(
    title = "Terminated Grants vs. Dollars, by Organization",
    x = "Number of terminated grants (log scale)",
    y = "Total obligated dollars (log scale)"
  ) +
  theme_minimal()











Code
top_orgs &lt;- nsf |&gt;
  filter(!is.na(org_name), !is.na(usaspending_obligated)) |&gt;
  group_by(org_name) |&gt;
  summarize(total_dollars = sum(usaspending_obligated)) |&gt;
  arrange(desc(total_dollars)) |&gt;
  slice_head(n = 15)

ggplot(top_orgs, aes(x = total_dollars, y = fct_reorder(org_name, total_dollars))) +
  geom_col(fill = "#d95f0e") +
  scale_x_continuous(labels = scales::label_dollar(scale = 1e-6, suffix = "M")) +
  labs(
    title = "Organizations with the most NSF funding terminated",
    x = "Total obligated dollars",
    y = NULL
  ) +
  theme_minimal()











Code
nsf |&gt; 
    group_by(org_state) |&gt; 
    summarize(num = n()) |&gt; 
    arrange(desc(num)) |&gt; 
    slice_head(n = 16) |&gt; 
    ggplot(aes(x=num,y = fct_reorder(org_state, num)))+
        geom_col(fill = "#2c7fb8") +
        labs(
            title = "NSF Grant Terminations by State",
            subtitle = "Top 16 States",
            x = "Number of Grants Terminated",
            y = NULL
        ) +
        theme_minimal()











Code
top_states &lt;- nsf |&gt; 
  filter(!is.na(org_state)) |&gt; 
  group_by(org_state) |&gt; 
  summarize(total = n()) |&gt; 
  arrange(desc(total)) |&gt; 
  slice_head(n=16)

cruz_states &lt;- nsf |&gt;
  filter(!is.na(org_state)) |&gt;
  group_by(org_state, in_cruz_list) |&gt;
  summarize(n_terminations = n(), .groups = "drop") |&gt; 
  inner_join(top_states, by = "org_state")

ggplot(cruz_states, aes(x = n_terminations,
                       y = fct_reorder(org_state, total),
                       fill = in_cruz_list))+
        geom_col() +
        labs(
            title = "NSF Terminations by State Against Cruz's List",
            subtitle = "Top 16 States",
            x = "Number of Grants Terminated",
            y = NULL, fill = "On Cruz's List"
        ) +
        theme_minimal()











Code
nsf |&gt; 
    group_by(in_cruz_list) |&gt; 
    summarize(num = n()) |&gt; 
    ggplot(aes(x=in_cruz_list, y=num, fill = in_cruz_list)) +
        geom_col() +
        geom_text(aes(label=num), vjust = -0.2) +
        labs(title = "Grant Terminations on Cruz's List", x = "On Cruz's List", y = "Number of Grants Terminated", fill = "Cruz's List") + theme_minimal()

